import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    cities = []

    idx = 1
    for _ in range(n):
        x = int(input_data[idx])
        c = input_data[idx+1]
        idx += 2
        cities.append((x, c))

    coords = [c[0] for c in cities]
    types = [c[1] for c in cities]

    byteland_indices = []
    berland_indices = []
    disputed_indices = []

    for i in range(n):
        if types[i] == 'B':
            byteland_indices.append(i)
        elif types[i] == 'R':
            berland_indices.append(i)
        else:
            disputed_indices.append(i)

    if not disputed_indices:
        total_cost = 0
        if len(byteland_indices) > 1:
            for i in range(len(byteland_indices) - 1):
                idx1 = byteland_indices[i]
                idx2 = byteland_indices[i+1]
                total_cost += coords[idx2] - coords[idx1]

        if len(berland_indices) > 1:
            for i in range(len(berland_indices) - 1):
                idx1 = berland_indices[i]
                idx2 = berland_indices[i+1]
                total_cost += coords[idx2] - coordinates[idx1]

        print(total_cost)
        return

    min_disputed_idx = disputed_indices[0]
    max_disputed_idx = disputed_indices[-1]

    cost = 0

    for i in range(n - 1):
        dist = coords[i+1] - coords[i]
        if i < min_disputed_idx or i >= max_disputed_idx:
            if types[i] == 'B' and types[i+1] == 'B':
                cost += dist
            elif types[i] == 'R' and types[i+1] == 'R':
                cost += dist

    for i in range(len(disputed_indices) - 1):
        idx1 = disputed_indices[i]
        idx2 = disputed_indices[i+1]
        cost += coords[idx2] - coords[idx1]

    if byteland_indices:
        first_b_idx = byteland_indices[0]
        last_b_idx = byteland_indices[-1]

        if first_b_idx < min_disputed_idx:
            dist_to_first_p = coords[min_disputed_idx] - coords[first_b_idx]
            cost += dist_to_first_p

        if last_b_idx > max_disputed_idx:
            dist_from_last_p = coords[last_b_idx] - coords[max_disputed_idx]
            cost += dist_from_last_p

    if berland_indices:
        first_r_idx = berland_indices[0]
        last_r_idx = berland_indices[-1]

        if first_r_idx < min_disputed_idx:
            dist_to_first_p = coords[disputed_indices[0]] - coords[first_r_idx]
            cost += dist_to_first_p

        if last_r_idx > max_disputed_idx:
            dist_from_last_p = coords[berland_indices[-1]] - coords[disputed_indices[-1]]
            cost += dist_from_last_p

    print(cost)

if __name__ == "__main__":
    main()
